    Bug 1924869 - Improve readability of MimeJSComponents.sys.mjs. r=freaktechnik


    This is not a functional change.

    `HEADER_OPTION_DECODE_2231` is only supported if used together with
    `HEADER_PARAMETER` (which is correctly stated in mimeParser.sys.mjs). It
    should not be specified in places where it is not having an effect to
    not trick the reader into thinking decoding according to RFC 2231 is
    supported.

    Differential Revision: https://phabricator.services.mozilla.com/D225717

diff --git a/mailnews/mime/src/MimeJSComponents.sys.mjs b/mailnews/mime/src/MimeJSComponents.sys.mjs
index 37ddb5ab927..82be26677fa 100644
--- a/mailnews/mime/src/MimeJSComponents.sys.mjs
+++ b/mailnews/mime/src/MimeJSComponents.sys.mjs
@@ -281,7 +281,9 @@ MimeAddressParser.prototype = {
     aHeader = aHeader || "";
     const value = MimeParser.parseHeaderField(
       aHeader,
-      MimeParser.HEADER_ADDRESS | MimeParser.HEADER_OPTION_ALL_I18N,
+      MimeParser.HEADER_ADDRESS |
+        MimeParser.HEADER_OPTION_ALLOW_RAW |
+        MimeParser.HEADER_OPTION_DECODE_2047,
       aCharset
     );
     return fixArray(value, aPreserveGroups);
@@ -290,9 +292,7 @@ MimeAddressParser.prototype = {
     aHeader = aHeader || "";
     const value = MimeParser.parseHeaderField(
       aHeader,
-      MimeParser.HEADER_ADDRESS |
-        MimeParser.HEADER_OPTION_DECODE_2231 |
-        MimeParser.HEADER_OPTION_DECODE_2047,
+      MimeParser.HEADER_ADDRESS | MimeParser.HEADER_OPTION_DECODE_2047,
       undefined
     );
     return fixArray(value, false);
@@ -528,7 +528,9 @@ MimeConverter.prototype = {
   decodeMimeHeader(aHeader, aDefaultCharset, aOverride, aUnfold) {
     let value = MimeParser.parseHeaderField(
       aHeader,
-      MimeParser.HEADER_UNSTRUCTURED | MimeParser.HEADER_OPTION_ALL_I18N,
+      MimeParser.HEADER_UNSTRUCTURED |
+        MimeParser.HEADER_OPTION_ALLOW_RAW |
+        MimeParser.HEADER_OPTION_DECODE_2047,
       aDefaultCharset
     );
     if (aUnfold) {
